import fs from 'node:fs';import{gzipSync}from'node:zlib';import{pathToFileURL}from'node:url';
const base=new URL('.',pathToFileURL(process.argv[2]));const{McpHost}=await import(new URL('host.js',base));const{DeterministicLiveSimulator,LiveMutationNotDispatchedError}=await import(new URL('live.js',base));
function clean(v){v=structuredClone(v);function walk(x){if(!x||typeof x!=='object')return;for(const[k,w]of Object.entries(x)){if(typeof w==='string'&&w.startsWith('warp_'))x[k]='$transaction';else if(k==='expiresAt')x[k]='$time';else walk(w);}}if(v?.result?.content?.[0]?.text)try{v.result.content[0].text=JSON.parse(v.result.content[0].text);}catch{}walk(v);return v;}
function setup(sim,kind){const clip=sim.state.tracks[0].clips[0];Object.assign(clip,{kind:'audio',isAudio:true,warpMarkers:[{sampleTime:0,beatTime:0},{sampleTime:100000,beatTime:2},{sampleTime:176400,beatTime:4}]});if(kind.startsWith('arrangement')){sim.state.arrangementClips.push({trackRef:'track:track-1',clip:{...structuredClone(clip),ref:'arrangement-clip:track-1:0',objectIdentity:'simulator:arrangement-clip:0'}});}}
function params(kind){const action=kind.split('-')[1]??'add';return{clipRef:kind.startsWith('arrangement')?'arrangement-clip:track-1:0':'clip:clip-1',action,beatTime:action==='add'?1:2,...(action==='move'?{distance:0.5}:{})};}
const rows=[];for(const kind of ['session-add','session-move','session-delete'])for(const action of ['preview','apply']){const valid=action==='preview'?params(kind):{transactionId:'missing',confirmation:'apply',idempotencyKey:'apply-key'};const cases=[null,[],{},0,false,'x',valid,{...valid,extra:true}];for(const key of action==='preview'?['clipRef','action','beatTime','distance']:Object.keys(valid)){const omitted={...valid};delete omitted[key];cases.push(omitted);for(const value of [null,[],{},false,true,-4,-2,-1,-0.5,0,0.5,1,2,4,6,1e308,'','x','a'.repeat(257)])cases.push({...valid,[key]:value});}for(const args of cases){const sim=new DeterministicLiveSimulator();setup(sim,kind);const host=new McpHost(sim);rows.push({action,args,result:clean(await host[action==='preview'?'liveWarpMarkerPreviewAsync':'liveWarpMarkerApplyAsync'](1,args))});}}
const workflows=[];for(const kind of ['session-add','session-move','session-delete','arrangement-add','arrangement-move','arrangement-delete'])for(const scenario of ['normal','expire','epoch','identity-edit','source-content','missing-markers','empty-markers','not-audio','missing-identity','apply-before','apply-after','apply-refusal','apply-no-effect','apply-read','apply-current-read','apply-preabort','apply-beat-drift','apply-sample-drift','apply-duplicate-marker','undo-before','undo-after','undo-refusal','undo-no-effect','undo-read','undo-current-read','undo-other-identity','undo-other-content','undo-sample-drift','undo-epoch']){
const sim=new DeterministicLiveSimulator(),calls=[],cache=new Map();setup(sim,kind);let fault='',fired=false,afterInvoke=false;const source=kind.startsWith('arrangement')?sim.state.arrangementClips[0].clip:sim.state.tracks[0].clips[0];if(scenario==='missing-identity')delete source.objectIdentity;if(scenario==='missing-markers')delete source.warpMarkers;if(scenario==='empty-markers')source.warpMarkers=[];if(scenario==='not-audio'){source.isAudio=false;source.kind='midi';}
function context(c){return c?{deadline:c.deadlineMs!==undefined,...(c.idempotencyKey?{idempotencyKey:c.idempotencyKey}:{}),...(c.transactionId?{transactionId:c.transactionId}:{})}:null;}
function readFault(){if(!fired&&((fault.endsWith('-read')&&afterInvoke)||fault==='apply-current-read'||fault==='undo-current-read')){fired=true;throw Error('injected authoritative read failure');}}
function invoke(i,c){calls.push(clean({method:'invoke',invocation:i,context:context(c)}));if(i.operation==='audio.warp-marker.read'){readFault();return sim.invoke(i);}const key=JSON.stringify([c?.transactionId,c?.idempotencyKey,i]);if(cache.has(key))return cache.get(key);if(!fired&&['before','refusal'].some(s=>fault.endsWith(s))){fired=true;throw fault.endsWith('refusal')?new LiveMutationNotDispatchedError('mutation was not dispatched: ownership changed'):Error('injected operation failure');}const noEffect=!fired&&fault.endsWith('no-effect');const result=noEffect?{ok:true}:sim.invoke(i);if(noEffect)fired=true;else cache.set(key,structuredClone(result));afterInvoke=true;if(!fired&&fault.endsWith('after')){fired=true;throw Error('injected operation failure');}if(!fired&&['apply-beat-drift','apply-sample-drift','apply-duplicate-marker'].includes(fault)){fired=true;if(fault==='apply-beat-drift')source.warpMarkers[0].beatTime=0.25;else if(fault==='apply-sample-drift')source.warpMarkers[0].sampleTime=9;else source.warpMarkers.push(structuredClone(source.warpMarkers[0]));}return result;}
const adapter={status:()=>sim.status(),snapshot:()=>sim.snapshot(),get:r=>sim.get(r),invoke:i=>invoke(i),subscribe:l=>sim.subscribe(l),reconnect:()=>sim.reconnect(),snapshotAsync:async(c,r)=>{calls.push(clean({method:'snapshot',request:r??null,context:context(c)}));readFault();return sim.snapshotAsync(c,r)},discoverAsync:async(r,c)=>{calls.push(clean({method:'discover',request:r,context:context(c)}));readFault();return sim.discoverAsync(r,c)},getAsync:async(r,c)=>{calls.push(clean({method:'get',reference:r,context:context(c)}));readFault();return sim.get(r)},invokeAsync:async(i,c)=>invoke(i,c),refreshStatusAsync:async(c)=>{calls.push(clean({method:'status',context:context(c)}));return sim.status()}};
const host=new McpHost(adapter),results=[],states=[];const args=params(kind);const preview=await host.liveWarpMarkerPreviewAsync(1,args);results.push(clean(preview));const body=preview.result?.content?.[0]?.text?JSON.parse(preview.result.content[0].text):{};const txid=body.transactionId;
if(txid){const record=host.clipLifecycleTransactions.get(txid);async function perform(action,key){const args={transactionId:txid,confirmation:action,idempotencyKey:key};const controller=new AbortController();if(scenario==='apply-preabort')controller.abort();results.push(clean(action==='apply'?await host.liveWarpMarkerApplyAsync(results.length+1,args,controller.signal):await host.liveUndoAsync(results.length+1,args)));states.push(clean(record));}
if(scenario==='expire')record.expiresAt=0;if(scenario==='epoch')sim.reconnect();if(scenario==='identity-edit')source.objectIdentity='other';if(scenario==='source-content')source.warpMarkers[0].beatTime=0.25;if(scenario.startsWith('apply-'))fault=scenario;
for(const key of ['apply-key','other-key','apply-key'])await perform('apply',key);fault='';fired=false;afterInvoke=false;
if(scenario==='undo-other-identity')source.objectIdentity='other';if(scenario==='undo-other-content')source.warpMarkers[0].beatTime=0.25;if(scenario==='undo-sample-drift')source.warpMarkers[0].sampleTime=123;if(scenario==='undo-epoch')sim.reconnect();if(scenario.startsWith('undo-')&&!['undo-other-identity','undo-other-content','undo-sample-drift','undo-epoch'].includes(scenario))fault=scenario;
for(const key of ['undo-key','other-undo-key','undo-key'])await perform('undo',key);fault='';fired=false;afterInvoke=false;await perform('undo','new-undo-key');}
workflows.push({kind,scenario,results,states,calls,state:sim.state});}
const evidence=[];for(const read of [null,[],{},false,3,'x',{markers:null},{markers:{}},{markers:'x'},{markers:[null]},{markers:[{}]},{markers:[{beatTime:0}]},{markers:[{sampleTime:0}]},{markers:[{sampleTime:0,beatTime:0}],revision:'wrong'},{markers:[{sampleTime:0,beatTime:0}],revision:false},{markers:[{sampleTime:0,beatTime:0,extra:5}]},{markers:[{sampleTime:0,beatTime:0},{sampleTime:1,beatTime:0}]}]){const sim=new DeterministicLiveSimulator();setup(sim,'session-add');sim.invokeAsync=async()=>structuredClone(read);const host=new McpHost(sim);evidence.push({read,result:clean(await host.liveWarpMarkerPreviewAsync(1,params('session-add')))});}
fs.writeFileSync(new URL('host-warp-oracle.json.gz',import.meta.url),gzipSync(JSON.stringify({rows,workflows,evidence}),{level:9}));console.log({rows:rows.length,workflows:workflows.length});
